let mapZoom=1;
function changeMapZoom(delta){mapZoom=Math.max(1,Math.min(1.42,Math.round((mapZoom+delta)*100)/100));const svg=document.querySelector('.hungary-map');if(svg)svg.style.setProperty('--map-zoom',String(mapZoom));$('mapZoomIn').disabled=mapZoom>=1.42;$('mapZoomOut').disabled=mapZoom<=1;}
